<?php
$lockName = htmlspecialchars((string)($_SESSION['user']['full_name'] ?? 'Pengguna'), ENT_QUOTES, 'UTF-8');
$lockCsrf = htmlspecialchars((string)($_SESSION['csrf'] ??= bin2hex(random_bytes(32))), ENT_QUOTES, 'UTF-8');
$lockBase = json_encode(APP_BASE);
$lockDestination = json_encode(APP_BASE . ((($_SESSION['user']['role'] ?? '') === 'admin') ? '/admin.php' : '/student.php'));
?>
<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Sesi Terkunci | Santri Go</title><style>
*{box-sizing:border-box}body{margin:0;min-height:100vh;display:grid;place-items:center;padding:20px;background:linear-gradient(135deg,#edf3fb,#dce8f7);font:15px Arial,sans-serif;color:#203653}.lock-card{width:min(100%,430px);padding:34px;border-radius:22px;background:#fff;box-shadow:0 24px 70px #1b365522;text-align:center}.lock-icon{width:66px;height:66px;margin:0 auto 18px;border-radius:20px;display:grid;place-items:center;background:#eaf1fb;color:#315f9f;font-size:30px}.lock-card h1{font-size:23px;margin:0 0 9px}.lock-card p{color:#718096;line-height:1.55;margin:0 0 22px}.lock-card label{display:block;text-align:left;font-size:13px;font-weight:700;margin:0 0 8px}.lock-card input{width:100%;height:48px;border:1px solid #d7e1ee;border-radius:11px;padding:0 14px;font-size:16px;outline:none}.lock-card button{width:100%;height:48px;margin-top:14px;border:0;border-radius:11px;background:#315f9f;color:#fff;font-weight:700;font-size:15px;cursor:pointer}.lock-error{min-height:20px;margin-top:12px;color:#bd3434;font-size:13px}.lock-user{font-weight:700;color:#315f9f}
</style></head><body><main class="lock-card"><div class="lock-icon">🔒</div><h1>Sesi Dikunci</h1><p>Tidak ada aktivitas selama 5 menit. Masukkan kembali password akun <span class="lock-user"><?= $lockName ?></span> untuk melanjutkan.</p><form id="unlockForm"><input type="hidden" name="csrf" value="<?= $lockCsrf ?>"><label for="unlockPassword">Password akun</label><input id="unlockPassword" name="password" type="password" autocomplete="current-password" required autofocus><button type="submit">Buka Kunci</button><div class="lock-error" id="unlockError" role="alert"></div></form></main><script>
(function(){const f=document.getElementById('unlockForm'),p=document.getElementById('unlockPassword'),e=document.getElementById('unlockError'),b=f.querySelector('button');f.addEventListener('submit',async function(ev){ev.preventDefault();e.textContent='';b.disabled=true;b.textContent='Memeriksa...';try{const r=await fetch(<?= $lockBase ?>+'/session_lock.php?action=unlock',{method:'POST',body:new FormData(f),credentials:'same-origin',headers:{'X-Requested-With':'XMLHttpRequest'}});const j=await r.json();if(j.success){location.replace(<?= $lockDestination ?>);return;}e.textContent=j.message||'Password tidak sesuai.';p.value='';p.focus();}catch(x){e.textContent='Tidak dapat menghubungi server. Coba lagi.';}finally{b.disabled=false;b.textContent='Buka Kunci';}});})();
</script></body></html>
